struct Counter {
    n: i32,
}

impl Counter {
    fn new() -> Self { Counter { n: 0 } }
    fn increment(&self) { self.n += 1; }
    fn get(&self) -> i32 { self.n }
}

fn main() {
    let c = Counter::new();
    c.increment();
    c.increment();
    c.increment();
    println!("{}", c.get());
}
